var a=`0731-jarret-de-boeuf`;var i=`world-0731`;var t=`TD`;var s=`central-africa`;var o=4;var r=156;var l={en:`Jarret de Boeuf`,ua:`Тушкована яловича гомілка`};var d={en:`Jarret de Boeuf is a Chad classic prepared with beef shank, yellow onion, carrot, tomato. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Тушкована яловича гомілка, страва кухні країни Чад зі складниками: яловича гомілка, жовта цибуля, морква, помідор. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`beef-shank`,850,`g`],[`yellow-onion`,220,`g`],[`sunflower-oil`,50,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 140 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 140 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:140,i:[[`beef-stock`,750,`ml`],[`carrot`,260,`g`],[`tomato`,250,`g`],[`bay-leaf`,2,`leaf`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,25,`g`],[`black-peppercorn`,4,`g`]]}];var u={slug:a,id:i,country:`TD`,region:s,servings:4,minutes:156,title:l,text:d,steps:g};export{t as country,u as default,i as id,r as minutes,s as region,o as servings,a as slug,g as steps,d as text,l as title};